/* Three stars, seven places: a checkpointed co-op adventure. */
const CP_KEY=new URLSearchParams(location.search).get('preview')==='1'?'little-walk-review-v1':'little-walk-campaign-v1';
const CP_NODES=[['market','星光集市','4–5 分钟','逛小摊，解开三件小事'],['memory','琉璃阁的回忆','3–4 分钟','走回十一那天的合照'],['water','水车与风的路','2–3 分钟','疏通水流，把风送到小屋'],['greenhouse','月光温室','4–6 分钟','接水、调光、配合采下星星'],['post','迷雾邮局','4–5 分钟','你读线索，我来解锁'],['bridge','星河归途','2–3 分钟','轮流接住彼此，过桥回家'],['home','亮着灯的小屋','1–2 分钟','把回忆与星星带回家']];
const CP_SYMBOLS=['❧','☁','☾','✦','☀'];
function freshCampaign(){return {started:false,active:null,route:null,done:[],cats:[],hints:{},message:'',waterPhase:2,market:{stall:null,done:[],sequence:[],orders:[-1,-1,-1],rings:[3,5,1]},green:{phase:0,rotations:[],colors:[0,0,0],harvest:0},post:{lock:0,code:'',route:[],stamps:[0,0,0,0]},roof:[]}}
let campaign=freshCampaign(),cpHolding=false,cpHoldOwner=null,cpSaveFailed=false;
const cpOldRender=render,cpOldNext=next,cpOldReset=reset,cpOldCollect=collectMemory;
const cpEscape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cpStars(){return ['market','greenhouse','post'].filter(n=>campaign.done.includes(n)).length}
function cpUnlocked(id){const index=CP_NODES.findIndex(n=>n[0]===id);return index===0||campaign.done.includes(id)||(index>0&&CP_NODES.slice(0,index).every(n=>campaign.done.includes(n[0])))}
function cpStop(){++journeyToken;cancelAnimationFrame(frame);cancelAnimationFrame(walkFrame);clearCoopTouches();holding.clear();transitioning=false;cpHolding=false;cpHoldOwner=null}
function cpMap(){cpStop();memory.active=false;campaign.started=true;campaign.active='map';campaign.message='';render()}
function cpFinish(id){if(!campaign.done.includes(id))campaign.done.push(id);chime(true);campaign.message='';cpMap()}
function cpStart(id){if(!cpUnlocked(id))return;cpStop();campaign.started=true;campaign.route=id;campaign.message='';memory.active=false;if(['market','greenhouse','post'].includes(id)){campaign.active=id}else{campaign.active=null;if(id==='memory'){stage=1;met=true;openMemory(memory.complete);return}if(id==='water')stage=campaign.waterPhase;else if(id==='bridge'){if(cpStars()!==3){cpMap();return}stage=4}else if(id==='home')stage=5}render()}
function cpReport(text){campaign.message=text;const el=document.querySelector('#cpMessage');if(el)el.textContent=text;cpSave()}
function cpHint(key,steps){const level=Math.min((campaign.hints[key]||0)+1,steps.length);campaign.hints[key]=level;cpReport(steps[level-1])}
function cpCat(id){if(campaign.cats.includes(id))return;campaign.cats.push(id);chime();cpReport(campaign.cats.length===3?'三张小猫便签集齐了。地图上的屋顶，现在可以去了。':'小猫递给你一张星星便签。它还会去另外两处地方。');render()}
function cpButton(id,label,cls='control'){return `<button id="${id}" class="${cls}">${label}</button>`}
function cpFrame(title,sub,body,actions='',hint=null){chapter.textContent='THREE STARS · '+title;document.querySelector('#skip').hidden=true;document.querySelector('#hint').textContent=cpSaveFailed?'本机暂时无法存档，请保持页面打开':'进度保存在这台设备 · 随时回到地图';app.innerHTML=`<section class="game cp-game"><div class="cp-heading"><div><div class="eyebrow">A LITTLE WALK / THREE STARS</div><h2>${title}</h2><p>${sub}</p></div><div class="cp-stars" aria-label="已收集${cpStars()}颗星星">${['market','greenhouse','post'].map(id=>`<span class="${campaign.done.includes(id)?'lit':''}">✦</span>`).join('')}</div></div>${body}<div class="cp-status" id="cpMessage" role="status">${cpEscape(campaign.message||'慢慢来，没有计时，也不会扣掉尝试机会。')}</div><div class="controls cp-actions">${actions}${hint?cpButton('cpHint','一点提示','text'):''}${['market','greenhouse','post'].includes(campaign.active)?cpButton('cpCat',campaign.cats.includes(campaign.active)?'✓ 收到小猫便签':'角落里有一只小猫','text'):''}</div></section>`;if(hint)document.querySelector('#cpHint').onclick=hint;const cat=document.querySelector('#cpCat');if(cat){cat.disabled=campaign.cats.includes(campaign.active);cat.onclick=()=>cpCat(campaign.active)}}
function cpMapArt(){const nodes=[[165,250,'market','🏮'],[340,160,'memory','▧'],[470,290,'water','≈'],[630,180,'greenhouse','❀'],[770,280,'post','✉'],[875,170,'bridge','✧']];const art=`<path d="M165 250 340 160 470 290 630 180 770 280 875 170" fill="none" stroke="#d6bbd2" stroke-width="3" stroke-dasharray="5 10"/>${nodes.map(([x,y,id,icon])=>`<g data-map="${id}" class="cp-map-node ${cpUnlocked(id)?'available':'locked'}" transform="translate(${x} ${y})" role="button" tabindex="${cpUnlocked(id)?0:-1}" aria-label="前往${CP_NODES.find(n=>n[0]===id)[1]}"><circle r="34" fill="#514b6b" stroke="${campaign.done.includes(id)?'#f6d69a':'#c2a7cb'}" stroke-width="2"/><circle r="27" fill="#72617d"/><text y="10" text-anchor="middle" font-size="26" fill="#f0d5ad">${campaign.done.includes(id)?'✓':icon}</text></g>`).join('')}`;return scene(art,character(65,320,true)+character(120,320,false))}
function renderCampaignMap(){const next=CP_NODES.find(n=>!campaign.done.includes(n[0])&&cpUnlocked(n[0]));cpFrame('把三颗星星，一起带回家。','一场按首次游玩约 20–30 分钟设计的冒险。每一段路，都可以中途停下再回来。',`<div class="cp-map-layout"><div class="cp-map-art">${cpMapArt()}<div class="cp-optional"><span>支线 · 小猫便签 ${campaign.cats.length}/3</span>${campaign.cats.length===3?cpButton('cpRoof','去屋顶看看流星 ♡','text'):''}</div></div><div class="cp-route-list">${CP_NODES.map(([id,title,time,desc],i)=>`<button data-node="${id}" class="cp-route ${campaign.done.includes(id)?'done':''}" ${cpUnlocked(id)?'':'disabled'}><span class="cp-route-num">${campaign.done.includes(id)?'✓':i+1}</span><span><strong>${title}</strong><small>${desc}</small></span><em>${time}</em></button>`).join('')}</div></div>`,next?cpButton('cpContinue','继续 · '+next[1]+' →','primary'):cpButton('cpContinue','回到亮着灯的小屋 →','primary'));document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>cpStart(b.dataset.node));document.querySelectorAll('[data-map]').forEach(el=>{el.onclick=()=>cpStart(el.dataset.map);el.onkeydown=e=>{if(e.key==='Enter'&&cpUnlocked(el.dataset.map))cpStart(el.dataset.map)}});document.querySelector('#cpContinue').onclick=()=>cpStart(next?next[0]:'home');const roof=document.querySelector('#cpRoof');if(roof)roof.onclick=()=>{campaign.active='roof';render()}}
function marketStalls(){const stalls=[['星图铺','把五个符号，排成正确的星路。','✦'],['点心店','读懂客人的口味，送对三份点心。','◒'],['旧书摊','转动旧书上的三道星环。','▤']];cpFrame('第一章 · 星光集市','摊主把三样东西交给了我们：一张星图、一份暖光点心，以及一段灯芯。',`<div class="cp-stalls">${stalls.map(([title,desc,icon],i)=>`<button class="cp-stall ${campaign.market.done.includes(i)?'done':''}" data-stall="${i}"><span class="cp-stall-icon">${icon}</span><h3>${title}</h3><p>${desc}</p><small>${campaign.market.done.includes(i)?'✓ 已拿到纪念物':'去和摊主聊聊 →'}</small></button>`).join('')}</div><div class="cp-inventory">${['星图','暖光点心','灯芯'].map((s,i)=>`<span class="${campaign.market.done.includes(i)?'owned':''}">${campaign.market.done.includes(i)?'✓':'·'} ${s}</span>`).join('')}</div>`,campaign.market.done.length===3?cpButton('marketReward','把灯点亮，收下第一颗星 →','primary'):'');document.querySelectorAll('[data-stall]').forEach(b=>b.onclick=()=>{campaign.market.stall=Number(b.dataset.stall);campaign.message='';render()});const reward=document.querySelector('#marketReward');if(reward)reward.onclick=()=>cpFinish('market')}
function marketDone(stall){if(!campaign.market.done.includes(stall))campaign.market.done.push(stall);campaign.market.stall=null;campaign.message='';chime(true);render()}
function renderMarket(){const m=campaign.market;if(m.stall===null){marketStalls();return}const back=()=>{m.stall=null;campaign.message='';render()};if(m.done.includes(m.stall)){cpFrame('摊主替我们保管着这件纪念物。','随时可以回集市，再看看其他小摊。',`<div class="cp-reward">✦<h3>${['星图','暖光点心','灯芯'][m.stall]}已经收好了。</h3></div>`,cpButton('stallBack','回到集市','primary'));document.querySelector('#stallBack').onclick=back;return}
if(m.stall===0){cpFrame('星图铺 · 五个符号的路','把摊主给的四条线索，变成一条完整的星路。',`<div class="cp-two"><div class="cp-note"><h3>摊主的纸条</h3><p>月亮在正中间。<br>星星紧跟在月亮之后。<br>太阳紧跟在星星之后。<br>叶子在云朵之前。</p></div><div class="cp-task"><div class="cp-sequence">${Array.from({length:5},(_,i)=>`<span>${m.sequence[i]===undefined?'·':CP_SYMBOLS[m.sequence[i]]}</span>`).join('')}</div><div class="cp-symbol-tray">${CP_SYMBOLS.map((s,i)=>`<button data-symbol="${i}" class="control" ${m.sequence.includes(i)?'disabled':''}>${s}</button>`).join('')}</div><p>依次点选符号，铺进五个位置。</p></div></div>`,`${cpButton('marketCheck','交给摊主看看','primary')}${cpButton('marketUndo','退回一个','control')}${cpButton('stallBack','回到集市','text')}`,()=>cpHint('market0',['先固定中间的月亮，再放它后面的两个符号。','从左到右：叶子、云、月亮、星星、太阳。']));document.querySelectorAll('[data-symbol]').forEach(b=>b.onclick=()=>{if(m.sequence.length<5)m.sequence.push(Number(b.dataset.symbol));render()});document.querySelector('#marketUndo').onclick=()=>{m.sequence.pop();render()};document.querySelector('#marketCheck').onclick=()=>{if(m.sequence.join(',')==='0,1,2,3,4')marketDone(0);else cpReport('还有一处没有对上纸条。没有关系，可以退回去再排。')};}
else if(m.stall===1){const foods=['桃子','粽子','月饼'],guests=['小猫','小兔','小狐狸'];cpFrame('点心店 · 把温暖分给谁','每位客人拿一份点心，每种点心只送一次。',`<div class="cp-two"><div class="cp-note"><h3>客人的留言</h3><p>小兔想要有叶子包着的点心。<br>小猫想要圆圆的，但不吃月饼。<br>小狐狸不要水果。</p></div><div class="cp-task cp-orders">${guests.map((s,i)=>`<div><strong>${s}</strong><button class="control" data-order="${i}">${m.orders[i]<0?'选择点心 ↻':foods[m.orders[i]]+' ↻'}</button></div>`).join('')}</div></div>`,`${cpButton('marketCheck','把点心送出去','primary')}${cpButton('stallBack','回到集市','text')}`,()=>cpHint('market1',['先把粽子留给小兔。再看看小猫排除了哪一种圆点心。','小猫拿桃子，小兔拿粽子，小狐狸拿月饼。']));document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.order);m.orders[i]=(m.orders[i]+1)%3;render()});document.querySelector('#marketCheck').onclick=()=>{if(m.orders.join(',')==='0,1,2')marketDone(1);else cpReport('有人还没有拿到想要的点心。再读一次他们的留言吧。')};}
else{const symbols=['❧','☁','☾','✦','☀','❀'];cpFrame('旧书摊 · 星环里的灯芯','每点一次星环，就会向前转一格。',`<div class="cp-two"><div class="cp-note"><h3>书页边上的字</h3><p>中间一环停在月亮。<br>左环比中环早两格。<br>右环比中环晚一格。</p><small>顺序：叶子 → 云 → 月亮 → 星星 → 太阳 → 花</small></div><div class="cp-task"><div class="cp-dials">${m.rings.map((n,i)=>`<button class="cp-dial" data-ring="${i}" aria-label="转动第${i+1}个星环">${symbols[n]}</button>`).join('')}</div></div></div>`,`${cpButton('marketCheck','试着打开旧书','primary')}${cpButton('stallBack','回到集市','text')}`,()=>cpHint('market2',['先把中环转到月亮，再沿顺序往前和往后数。','三环从左到右：叶子、月亮、星星。']));document.querySelectorAll('[data-ring]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.ring);m.rings[i]=(m.rings[i]+1)%6;render()});document.querySelector('#marketCheck').onclick=()=>{if(m.rings.join(',')==='0,2,3')marketDone(2);else cpReport('书页轻轻动了一下，但星环还没对齐。再转一转。')};}document.querySelector('#stallBack').onclick=back}
const CP_PORTS={L:[0,1],I:[0,2],X:[0,1,2,3]};
const CP_PIPES=[{w:3,h:3,types:['L','I','L','L','I','I','L','I','L'],solution:[1,1,2,3,0,0,1,1,0],source:3,targets:[8]},{w:4,h:3,types:['L','L','I','I','I','X','I','I','L','L','I','I'],solution:[0,1,1,1,1,0,1,1,0,0,1,1],source:4,targets:[3,7,11]}];
function cpRotations(round){const g=campaign.green;if(!g.rotations[round])g.rotations[round]=CP_PIPES[round].solution.map((r,i)=>(r+i%3+1)%4);return g.rotations[round]}
function pipePorts(round,index){const layout=CP_PIPES[round];return CP_PORTS[layout.types[index]].map(p=>(p+cpRotations(round)[index])%4)}
function pipeFlow(round){const d=CP_PIPES[round],seen=new Set();if(!pipePorts(round,d.source).includes(3))return seen;const queue=[d.source];while(queue.length){const i=queue.shift();if(seen.has(i))continue;seen.add(i);for(const p of pipePorts(round,i)){const x=i%d.w,y=Math.floor(i/d.w),nx=x+[0,1,0,-1][p],ny=y+[-1,0,1,0][p];if(nx<0||ny<0||nx>=d.w||ny>=d.h)continue;const j=ny*d.w+nx;if(pipePorts(round,j).includes((p+2)%4)&&!seen.has(j))queue.push(j)}}return seen}
function pipeSolved(round){const flow=pipeFlow(round);return CP_PIPES[round].targets.every(i=>flow.has(i)&&pipePorts(round,i).includes(1))}
function pipeSVG(ports){const ends=[[30,3],[57,30],[30,57],[3,30]];return `<svg viewBox="0 0 60 60" aria-hidden="true">${ports.map(p=>`<path d="M30 30L${ends[p][0]} ${ends[p][1]}"/>`).join('')}<circle cx="30" cy="30" r="5"/></svg>`}
function renderGreenhouse(){const g=campaign.green;if(g.phase<2){const round=g.phase,d=CP_PIPES[round],wet=pipeFlow(round);cpFrame(`月光温室 · ${round===0?'先接通一株花':'让水分成三条路'}`,round===0?'轻点水管转动方向，水从左侧箭头流进来。':'左边读水路，右边转动管道。三株花都需要接到右侧的出水口。',`<div class="cp-two"><div class="cp-note"><div class="cp-greenhouse-icon">❀</div><h3>${round===0?'温室管理员的便签':'把水送给每一株花'}</h3><p>${round===0?'先让水往上走，再从上方绕到右下角的花。':'中央的十字管会分流。上、中、下三条水路，都要通向右边。'}</p><small>亮蓝的水管表示水已经流到这里。空心管还没有接通。</small></div><div class="cp-task"><div class="cp-pipe-board" style="--cols:${d.w}">${d.types.map((type,i)=>`<button class="cp-pipe ${wet.has(i)?'wet':''} ${i===d.source?'source':''} ${d.targets.includes(i)?'outlet':''}" data-pipe="${i}" aria-label="转动第${i+1}格水管，出口方向${pipePorts(round,i).map(p=>['上','右','下','左'][p]).join('、')}" ${type==='X'?'disabled':''}>${pipeSVG(pipePorts(round,i))}${i===d.source?'<i>→</i>':''}${d.targets.includes(i)?'<em>❀</em>':''}</button>`).join('')}</div></div></div>`,cpButton('pipeCheck','试着送水 →','primary'),()=>cpHint('pipe'+round,[round===0?'从左侧入口向上转，在顶行走到最右边，再向下走。':'入水口横过来，中央分流：上方转弯后向右，下方也转弯向右。','水管只能在相邻格的接口相对时接通。可以沿着已经变蓝的管道，一格一格往前检查。']));document.querySelectorAll('[data-pipe]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.pipe);cpRotations(round)[i]=(cpRotations(round)[i]+1)%4;campaign.message='';render()});document.querySelector('#pipeCheck').onclick=()=>{if(pipeSolved(round)){g.phase++;campaign.message='';chime(true);render()}else cpReport('还有花没有接到水。沿着蓝色水路，看看是在哪一格断开的。')};return}
if(g.phase===2){const colors=['黄昏金','暮光紫','夜空蓝'];cpFrame('月光温室 · 给花调一束光','左边读配方，右边调灯。水有了，颜色也要刚刚好。',`<div class="cp-two"><div class="cp-note"><h3>我这边的配方</h3><p>☾ 月亮花，喜欢夜空的颜色。<br>☀ 太阳花，想留住黄昏。<br>✦ 星星花，喜欢暮光的紫。</p></div><div class="cp-task cp-flower-lights">${['☾','☀','✦'].map((s,i)=>`<button data-color="${i}" class="cp-flower color-${g.colors[i]}"><span>${s}</span><small>${colors[g.colors[i]]} ↻</small></button>`).join('')}</div></div>`,cpButton('lightCheck','让花开起来 →','primary'),()=>cpHint('light',['按月亮、太阳、星星的顺序，去找配方里的三种颜色。','月亮用蓝色，太阳用金色，星星用紫色。']));document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.color);g.colors[i]=(g.colors[i]+1)%3;render()});document.querySelector('#lightCheck').onclick=()=>{if(g.colors.join(',')==='2,0,1'){g.phase=3;campaign.message='';chime(true);render()}else cpReport('花苞还在等合适的光。把配方读给对方听，再调一次。')};return}
if(g.phase===3){renderHarvest();return}cpFrame('温室亮了，第二颗星也醒了。','这颗星，来自两个人一起照顾过的花。',`<div class="cp-reward cp-life-star">✦<h3>生长之星</h3><p>水路、光线，还有你们配合的节奏，<br>一起把它唤醒了。</p></div>`,cpButton('greenReward','收好第二颗星，回到地图 →','primary'));document.querySelector('#greenReward').onclick=()=>cpFinish('greenhouse')}
const CP_HARVEST=[2,0,1,0,2,1];
function renderHarvest(){cpHolding=false;cpHoldOwner=null;const g=campaign.green;cpFrame('月光温室 · 我守着光，你来采星','左边持续按住灯光，右边按照配方点花。可以停下来，已经完成的步骤会保留。',`<div class="cp-two"><div class="cp-note"><h3>我这边的采摘顺序</h3><p class="cp-harvest-order">✦ → ☾ → ☀ → ☾ → ✦ → ☀</p><button id="harvestHold" class="control cp-harvest-hold">我 · 按住灯光</button><small>另一位玩家点右边的花。没有灯光时，花不会被采下。</small></div><div class="cp-task"><div class="cp-harvest-plants">${['☾','☀','✦'].map((s,i)=>`<button data-harvest="${i}" class="cp-flower color-${[2,0,1][i]}"><span>${s}</span></button>`).join('')}</div><div id="harvestProgress" class="cp-harvest-progress">已采好 ${g.harvest} / 6</div></div></div>`,cpButton('harvestReset','重新对一遍顺序','text'),()=>cpHint('harvest',['先按住左侧灯光，再由另一只手点右侧的花。可以一边读顺序，一边采。','从右侧花的位置看，顺序是：第3、第1、第2、第1、第3、第2。']));const hold=document.querySelector('#harvestHold');hold.onpointerdown=e=>{e.preventDefault();if(cpHoldOwner!==null)return;cpHoldOwner=e.pointerId;cpHolding=true;hold.setPointerCapture(e.pointerId);hold.classList.add('active')};const release=e=>{if(e.pointerId!==cpHoldOwner)return;cpHolding=false;cpHoldOwner=null;hold.classList.remove('active')};hold.onpointerup=release;hold.onpointercancel=release;hold.onlostpointercapture=release;hold.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();cpHolding=true;hold.classList.add('active')}};hold.onkeyup=()=>{cpHolding=false;hold.classList.remove('active')};document.querySelectorAll('[data-harvest]').forEach(b=>{let touchUntil=0;b.onpointerup=e=>{if(e.pointerType==='touch'){e.preventDefault();touchUntil=performance.now()+700;b.click()}};b.onclick=e=>{if(e.isTrusted&&performance.now()<touchUntil)return;if(!cpHolding){cpReport('灯光还没有亮。请另一位玩家先按住左侧按钮。');return}if(Number(b.dataset.harvest)!==CP_HARVEST[g.harvest]){g.harvest=0;cpReport('采错了一朵，不过花还在。一起从顺序的开头再来。')}else{g.harvest++;chime()}document.querySelector('#harvestProgress').textContent=`已采好 ${g.harvest} / 6`;cpSave();if(g.harvest===6){cpHolding=false;cpHoldOwner=null;g.phase=4;campaign.message='';chime(true);render()}}});document.querySelector('#harvestReset').onclick=()=>{g.harvest=0;campaign.message='';render()}}
const CP_ROUTE=['right','right','up','left','up','right','right','down'];
function cpRoutePosition(){let x=0,y=3;for(const d of campaign.post.route){x+=({left:-1,right:1}[d]||0);y+=({up:-1,down:1}[d]||0)}return{x,y}}
function postMove(d){const p=cpRoutePosition(),x=p.x+({left:-1,right:1}[d]||0),y=p.y+({up:-1,down:1}[d]||0);if(x<0||x>3||y<0||y>3){cpReport('已经走到这条街的边缘了。');return}if(campaign.post.route.length>=8){cpReport('八枚路线邮戳已经盖满。可以核对，或撤销一步。');return}campaign.post.route.push(d);render()}
function renderPost(){const p=campaign.post;if(p.lock===0){cpFrame('迷雾邮局 · 第一封信','左边查看符号的含义，读给右边的开锁人听。',`<div class="cp-two"><div class="cp-note cp-secret"><h3>我这边：符号对照表</h3><div id="postLegend" class="cp-hidden-clue"><p>☾ = 4　✦ = 1<br>❀ = 7　☁ = 3</p></div><button id="postPeek" class="control">按住，查看我的线索</button><small>松开会折起纸条。可以反复查看。</small></div><div class="cp-task"><h3>你这边：锁上的符号</h3><div class="cp-lock-symbols">☁　☾　✦</div><div class="cp-digits">${Array.from({length:3},(_,i)=>`<span>${p.code[i]||'·'}</span>`).join('')}</div><div class="cp-keypad">${[1,2,3,4,5,6,7,8,9,0].map(n=>`<button data-digit="${n}" class="control">${n}</button>`).join('')}</div></div></div>`,`${cpButton('postCheck','核对这封信','primary')}${cpButton('postUndo','退回一位','control')}`,()=>cpHint('post0',['先读右侧三个符号的先后顺序，再去左侧找对应数字。','云是3，月亮是4，星星是1。密码是341。']));const peek=document.querySelector('#postPeek'),legend=document.querySelector('#postLegend');peek.onpointerdown=e=>{e.preventDefault();peek.setPointerCapture(e.pointerId);legend.classList.add('visible')};peek.onpointerup=peek.onpointercancel=peek.onlostpointercapture=()=>legend.classList.remove('visible');peek.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();legend.classList.add('visible')}};peek.onkeyup=()=>legend.classList.remove('visible');document.querySelectorAll('[data-digit]').forEach(b=>b.onclick=()=>{if(p.code.length<3)p.code+=b.dataset.digit;document.querySelectorAll('.cp-digits span').forEach((el,i)=>el.textContent=p.code[i]||'·');cpSave()});document.querySelector('#postUndo').onclick=()=>{p.code=p.code.slice(0,-1);document.querySelectorAll('.cp-digits span').forEach((el,i)=>el.textContent=p.code[i]||'·');cpSave()};document.querySelector('#postCheck').onclick=()=>{if(p.code==='341'){p.lock=1;campaign.message='';chime(true);render()}else cpReport('符号和数字还没有一一对应。把顺序再读给对方一次。')};return}
if(p.lock===1){const pos=cpRoutePosition();cpFrame('迷雾邮局 · 把信送到正确的街角','一人读路线，一人移动邮差。按顺序走满八步，才能盖齐邮戳。',`<div class="cp-two"><div class="cp-note"><h3>我这边：信封上的路线</h3><p class="cp-route-instructions">右、右、上、左、<br>上、右、右、下。</p><p>从左下角的起点出发。<br>每走一步，留下一枚邮戳。</p><small>已经走了 ${p.route.length} / 8 步</small></div><div class="cp-task"><div class="cp-post-grid">${Array.from({length:16},(_,i)=>`<span class="${i%4===pos.x&&Math.floor(i/4)===pos.y?'here':''}">${i%4===pos.x&&Math.floor(i/4)===pos.y?'✉':String.fromCharCode(65+i)}</span>`).join('')}</div><div class="dpad">${[['up','↑'],['left','←'],['down','↓'],['right','→']].map(([d,s])=>`<button class="control" data-post-dir="${d}">${s}</button>`).join('')}</div></div></div>`,`${cpButton('postCheck','核对路线邮戳','primary')}${cpButton('routeUndo','退回一步','control')}${cpButton('routeReset','回到起点','text')}`,()=>cpHint('post1',['先往右走两格，再向上走一格。慢慢读，每次只走一步。','完整方向：右、右、上、左、上、右、右、下。终点在L，但邮戳顺序也要正确。']));document.querySelectorAll('[data-post-dir]').forEach(b=>b.onclick=()=>postMove(b.dataset.postDir));document.querySelector('#routeUndo').onclick=()=>{p.route.pop();render()};document.querySelector('#routeReset').onclick=()=>{p.route=[];render()};document.querySelector('#postCheck').onclick=()=>{if(p.route.join(',')===CP_ROUTE.join(',')){p.lock=2;campaign.message='';chime(true);render()}else cpReport('有一枚邮戳的位置不对。可以撤销到上个路口，再跟着信封走。')};return}
if(p.lock===2){const symbols=['☾','❀','✦','☁'];cpFrame('迷雾邮局 · 最后一排邮票','左边读位置关系，右边转动四枚邮票。每种图案只出现一次。',`<div class="cp-two"><div class="cp-note"><h3>我这边：邮票摆放规则</h3><p>星星在最后。<br>月亮既不是第一，也不是最后。<br>花紧紧跟在月亮后面。<br>云在星星前面。</p></div><div class="cp-task"><div class="cp-dials cp-four-dials">${p.stamps.map((n,i)=>`<button class="cp-dial" data-stamp="${i}" aria-label="转动第${i+1}枚邮票">${symbols[n]}</button>`).join('')}</div><p>每点一次，图案会换到下一枚。</p></div></div>`,cpButton('postCheck','把信封合上 →','primary'),()=>cpHint('post2',['把月亮与花看成相邻的一组。最后一位已经留给了星星。','从左到右：云、月亮、花、星星。']));document.querySelectorAll('[data-stamp]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.stamp);p.stamps[i]=(p.stamps[i]+1)%4;render()});document.querySelector('#postCheck').onclick=()=>{if(p.stamps.join(',')==='3,0,1,2'){p.lock=3;campaign.message='';chime(true);render()}else cpReport('邮票顺序还差一点。先把月亮和花放在一起。')};return}cpFrame('最后一封信，送到了。','第三颗星属于愿意互相解释、互相等待的两个人。',`<div class="cp-reward">✦<h3>回应之星</h3><p>三颗星都在了。<br>现在，我们可以一起去那座星光桥。</p></div>`,cpButton('postReward','收好第三颗星，回到地图 →','primary'));document.querySelector('#postReward').onclick=()=>cpFinish('post')}
function renderRoof(){cpFrame('支线 · 屋顶上的小猫','三张便签指向了这里。点亮六颗星，可以留下一小片属于今晚的星空。',`<div class="cp-roof"><div class="cp-roof-sky">${Array.from({length:6},(_,i)=>`<button data-roof="${i}" class="${campaign.roof.includes(i)?'on':''}" style="--x:${[18,35,47,65,78,50][i]}%;--y:${[50,25,47,25,50,72][i]}%" aria-label="点亮第${i+1}颗星">✦</button>`).join('')}<p>${campaign.roof.length===6?'星星都亮了。来，靠近一点。':'点一颗星，让它亮起来。'}</p></div><div class="cp-roof-pair"><svg viewBox="0 0 1000 140" aria-label="一起坐在屋顶的两个人"><defs>${daylightDefs}</defs>${character(430,70,true)+character(490,70,false)}</svg></div></div>`,cpButton('roofBack','回到地图','primary'));document.querySelectorAll('[data-roof]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.roof);if(!campaign.roof.includes(i)){campaign.roof.push(i);chime();render()}});document.querySelector('#roofBack').onclick=cpMap}
function cpSave(){if(!campaign.started)return;try{const data={version:1,campaign:{...campaign,message:''},runtime:{stage,met,handInHand,worldAwake,water,wind,puzzle,joined,bridge,coopPhase,coopAmount,unwrapped,letterOpen},memory:{...memory,clues:[...memory.clues]}};localStorage.setItem(CP_KEY,JSON.stringify(data));cpSaveFailed=false}catch{cpSaveFailed=true}}
function cpSafeArray(a,max,valueMax,fallback){return Array.isArray(a)&&a.length<=max&&a.every(n=>Number.isInteger(n)&&n>=0&&n<=valueMax)?a:fallback}
function cpRestore(){try{const s=JSON.parse(localStorage.getItem(CP_KEY)||'null');if(!s||s.version!==1||!s.campaign||!s.runtime||!s.memory)return false;const c=s.campaign,r=s.runtime,m=s.memory;campaign.album=c.album;campaign.town=c.town;const fresh=freshCampaign();campaign.started=c.started===true;campaign.active=['map','market','greenhouse','post','roof'].includes(c.active)?c.active:null;campaign.route=CP_NODES.some(n=>n[0]===c.route)?c.route:null;campaign.done=Array.isArray(c.done)?[...new Set(c.done.filter(id=>CP_NODES.some(n=>n[0]===id)))]:[];campaign.cats=Array.isArray(c.cats)?[...new Set(c.cats.filter(id=>['market','greenhouse','post'].includes(id)))]:[];campaign.roof=cpSafeArray(c.roof,6,5,[]);campaign.waterPhase=c.waterPhase===3?3:2;
const mm=c.market||{};campaign.market={stall:Number.isInteger(mm.stall)&&mm.stall>=0&&mm.stall<=2?mm.stall:null,done:cpSafeArray(mm.done,3,2,[]),sequence:cpSafeArray(mm.sequence,5,4,[]),orders:Array.isArray(mm.orders)&&mm.orders.length===3&&mm.orders.every(n=>Number.isInteger(n)&&n>=-1&&n<=2)?mm.orders:[-1,-1,-1],rings:cpSafeArray(mm.rings,3,5,[]).length===3?mm.rings:fresh.market.rings};const gg=c.green||{};campaign.green={phase:Number.isInteger(gg.phase)?clamp(gg.phase,0,4):0,rotations:[],colors:cpSafeArray(gg.colors,3,2,[]).length===3?gg.colors:[0,0,0],harvest:Number.isInteger(gg.harvest)?clamp(gg.harvest,0,6):0};for(let i=0;i<2;i++){const a=gg.rotations?.[i];if(cpSafeArray(a,CP_PIPES[i].types.length,3,[]).length===CP_PIPES[i].types.length)campaign.green.rotations[i]=a}const pp=c.post||{};campaign.post={lock:Number.isInteger(pp.lock)?clamp(pp.lock,0,3):0,code:typeof pp.code==='string'&&/^\d{0,3}$/.test(pp.code)?pp.code:'',route:Array.isArray(pp.route)&&pp.route.length<=8?pp.route.filter(d=>['up','down','left','right'].includes(d)):[],stamps:cpSafeArray(pp.stamps,4,3,[]).length===4?pp.stamps:[0,0,0,0]};
stage=Number.isInteger(r.stage)?clamp(r.stage,0,5):1;met=!!r.met;handInHand=!!r.handInHand;worldAwake=!!r.worldAwake;water=Number.isInteger(r.water)?clamp(r.water,0,3):0;if(cpSafeArray(r.wind,3,3,[]).length===3)wind=r.wind;const pu=r.puzzle;const xy=a=>Array.isArray(a)&&a.length===2&&a.every(Number.isInteger)&&a[0]>=1&&a[0]<=5&&a[1]>=1&&a[1]<=4;if(pu&&xy(pu.player)&&Array.isArray(pu.boxes)&&pu.boxes.length===2&&pu.boxes.every(xy))puzzle={player:pu.player,boxes:pu.boxes,history:[],moves:Number.isInteger(pu.moves)?Math.max(0,pu.moves):0};joined=!!r.joined;bridge=!!r.bridge;coopPhase=Number.isInteger(r.coopPhase)?clamp(r.coopPhase,0,3):0;coopAmount=Number.isFinite(r.coopAmount)?clamp(r.coopAmount,0,.999):0;unwrapped=!!r.unwrapped;letterOpen=!!r.letterOpen;
memory=freshMemory();memory.active=!!m.active&&!campaign.active;memory.complete=!!m.complete;memory.replay=!!m.replay;memory.step=Number.isInteger(m.step)?clamp(m.step,0,3):0;memory.clues=new Set(Array.isArray(m.clues)?m.clues.filter(id=>memoryClues.some(c=>c.id===id)):[]);if(cpSafeArray(m.order,6,5,[]).length===6&&new Set(m.order).size===6)memory.order=m.order;memory.moves=Number.isInteger(m.moves)?Math.max(0,m.moves):0;for(const id of ['girl','boy'])if(m.poses?.[id]&&Number.isFinite(m.poses[id].x)&&Number.isFinite(m.poses[id].y))memory.poses[id]={x:clamp(m.poses[id].x,200,800),y:clamp(m.poses[id].y,250,306),ready:!!m.poses[id].ready};if(!campaign.started)return false;return true}catch{campaign=freshCampaign();return false}}
function cpDecorate(){const button=document.querySelector('#cpMapButton');button.hidden=!campaign.started;button.textContent=`地图 · ${cpStars()}/3 ✦`;if(!campaign.started&&stage===1&&met&&!memory.active){const entry=document.querySelector('#memoryStart');if(entry){entry.textContent='看看小镇地图 ✦';entry.onclick=cpMap}const depart=document.querySelector('#depart');if(depart)depart.textContent='和我去找三颗星星 →'}if(campaign.started)document.querySelector('#skip').hidden=true;if(campaign.started&&campaign.route==='bridge'&&stage===5){if(!campaign.done.includes('bridge'))campaign.done.push('bridge');if(!campaign.done.includes('home'))campaign.done.push('home');campaign.route='home'}cpSave()}
const cpMapButton=document.createElement('button');cpMapButton.id='cpMapButton';cpMapButton.className='text';cpMapButton.hidden=true;cpMapButton.onclick=cpMap;document.querySelector('header').insertBefore(cpMapButton,document.querySelector('#restart'));
render=function(){if(campaign.active==='map')renderCampaignMap();else if(campaign.active==='market')renderMarket();else if(campaign.active==='greenhouse')renderGreenhouse();else if(campaign.active==='post')renderPost();else if(campaign.active==='roof')renderRoof();else cpOldRender();cpDecorate()};
next=function(){if(stage===1&&met&&!memory.active){cpMap();return}if(campaign.started&&campaign.route==='water'&&stage===2)campaign.waterPhase=3;if(campaign.started&&campaign.route==='water'&&stage===3){exitTogether(()=>cpFinish('water'));return}cpOldNext()};
collectMemory=function(){if(campaign.started){memory.active=false;memory.complete=true;cpFinish('memory')}else cpOldCollect()};
reset=function(){cpStop();campaign=freshCampaign();try{localStorage.removeItem(CP_KEY)}catch{}cpOldReset();cpDecorate()};document.querySelector('#restart').onclick=reset;document.querySelector('#brand').onclick=e=>{e.preventDefault();reset()};
window.addEventListener('blur',()=>{cpHolding=false;cpHoldOwner=null;document.querySelector('#harvestHold')?.classList.remove('active');document.querySelector('#postLegend')?.classList.remove('visible');cpSave()});document.addEventListener('visibilitychange',()=>{if(document.hidden){cpHolding=false;cpHoldOwner=null;cpSave()}});window.addEventListener('pagehide',cpSave);document.addEventListener('pointerup',()=>setTimeout(cpSave,0));
const cpParams=new URLSearchParams(location.search);if(cpParams.get('fresh')==='1'){reset()}else{cpRestore();if(cpParams.get('chapter')==='memory'){campaign.started=true;campaign.route='memory';campaign.active=null;stage=1;met=true;memory.active=true;memory.replay=memory.complete;render()}else if(cpParams.get('chapter')==='map'){cpMap()}else render()}
